{
  "title": "The Glass Diver's Rescue",
  "gate_token": "id3jZUPOER6yO9LQe8NiOQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue begins at the ruined city gates.",
      "visual_description": "A shattered stone gate, half-collapsed, with old royal banners torn and hanging. Glass Diver peers through a broken mirror shard on the ground.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara reads a map of temptations.",
      "visual_description": "Mara the Cartographer kneels on rubble, unrolling a parchment map that glows faintly, while a clockwork tin fox sniffs the air beside her.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "An oil lamp with a single flaming eye flickers on a broken pillar, its light casting long shadows across a twisted spiral tower in the distance.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver swims through a magic door.",
      "visual_description": "Glass Diver presses a hand against a shimmering magic door set in a wall of rubble, his diving helmet reflecting the distorted city beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Tin Fox scouts the castle gates.",
      "visual_description": "The small metal fox creeps through a cracked archway, its blue glass eyes scanning a courtyard littered with fallen banners and broken statues.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a safe path past armored patrols.",
      "visual_description": "Mara crouches behind a crumbling wall, ink-stained fingers tracing a route on her map while distant armored figures march in the fog.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a dragon rumor trap.",
      "visual_description": "The lamp's eye glows red as it projects a shadow of a dragon onto a wall, warning of a false rumor meant to lure rescuers into a pit.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver rescues a frightened townsfolk from a cursed tower.",
      "visual_description": "Glass Diver climbs through a cracked window into a dark tower room, reaching out to a trembling figure huddled in the corner.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping Tax Collector blocks the path.",
      "visual_description": "The Sleeping Tax Collector snores loudly on a pile of ledgers, stamped papers stuck to his sleeves, blocking a narrow passage with his bulk.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Tin Fox distracts the patrols with a noise.",
      "visual_description": "The tin fox winds its tail and rolls a loose stone down a stairway, clattering to draw armored boots away from the group.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a hidden passage behind a magic door.",
      "visual_description": "Mara presses a compass against a stone wall, which dissolves into a shimmering magic door revealing a dark corridor.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp lights the way through the tunnel.",
      "visual_description": "The lamp floats ahead, its flame casting a warm glow on damp stone walls lined with old royal banners that stir as if alive.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver confronts a sealed iron door.",
      "visual_description": "Glass Diver stands before a massive iron door covered in frost, his reflection staring back from its icy surface.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Sleeping Tax Collector wakes and demands a toll.",
      "visual_description": "The tax collector stirs, blinks, and holds out a hand for stamped papers while the group waits impatiently in a crumbling hall.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox unlocks the iron door with a key.",
      "visual_description": "The tin fox inserts a key from its tail into the iron door's lock, gears whirring as the door groans open.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group escapes across a crumbling bridge.",
      "visual_description": "A stone bridge spans a deep chasm, cracks spreading as Glass Diver leads the rescued figure across, with Mara and the tin fox close behind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Oracle Lamp collapses the bridge behind them.",
      "visual_description": "The lamp's flame flares, sending a shockwave that shatters the bridge into rubble, cutting off pursuit.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The rescuers emerge from the ruined city at dawn.",
      "visual_description": "The group stands on a hill overlooking the ruined city as the sun rises, old royal banners fluttering in the wind behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

